import { ETIQUETA_TIPO, formatoFechaCorta, formatoFechaLarga, formatoPesos, sentidoMovimiento } from "../utils/formato";

const SIGNO = { credito: "+ ", debito: "− ", apartado: "", neutro: "" };

/**
 * Movimientos como filas de libreta: fecha, concepto con línea punteada y
 * monto. Si se pasa `cuentaId`, el signo se calcula desde esa cuenta.
 */
export function Extracto({ transacciones, cuentaId, nombresBolsillo = {} }) {
  return (
    <ol className="extracto">
      {transacciones.map((t) => {
        // `_cuenta` permite mezclar movimientos de varias cuentas propias.
        const referencia = cuentaId ?? t._cuenta;
        const sentido = referencia ? sentidoMovimiento(t, referencia) : "neutro";
        const bolsillo = t.bolsilloId ? nombresBolsillo[t.bolsilloId] : null;
        const detalle = [
          bolsillo ? `«${bolsillo}»` : null,
          t.tipo === "transferencia" && referencia
            ? sentido === "debito"
              ? `a cuenta #${t.cuentaDestinoId}`
              : `desde cuenta #${t.cuentaOrigenId}`
            : null,
          t.descripcion,
        ]
          .filter(Boolean)
          .join(" · ");

        return (
          <li key={`${t.id}-${referencia ?? ""}`} className="extracto__fila">
            <time className="extracto__fecha num" dateTime={t.fecha} title={formatoFechaLarga(t.fecha)}>
              {formatoFechaCorta(t.fecha)}
            </time>
            <span className="extracto__concepto">
              <strong>{ETIQUETA_TIPO[t.tipo] || t.tipo}</strong>
              {detalle ? <span>{detalle}</span> : null}
            </span>
            <span className={`extracto__monto num ${sentido}`}>
              {SIGNO[sentido]}
              {formatoPesos(t.monto)}
            </span>
          </li>
        );
      })}
    </ol>
  );
}

import { useState } from "react";
import { apartar, depositar, devolver, retirar, transferir } from "../services/recursos.service";
import { formatoPesos } from "../utils/formato";
import { AvisoError, Campo, CampoMonto } from "./Formulario";

const MAXIMO_TRANSACCION = 2000000; // Regla 5 del negocio (CHECK en BD)

const TEXTOS = {
  retiro: { boton: "Retirar", exito: "Retiro registrado." },
  transferencia: { boton: "Transferir", exito: "Transferencia registrada." },
  deposito: { boton: "Depositar", exito: "Depósito registrado." },
  apartar: { boton: "Apartar en el bolsillo", exito: "Dinero apartado." },
  devolver: { boton: "Devolver a la cuenta", exito: "Dinero devuelto a la cuenta." },
};

/**
 * Un solo formulario para los cinco movimientos. El backend valida
 * montos, propiedad de la cuenta y saldo disponible; aquí solo se guía.
 */
export function FormularioMovimiento({ tipo, cuenta, bolsillo, disponible, otrasCuentas = [], alTerminar }) {
  const [monto, setMonto] = useState("");
  const [descripcion, setDescripcion] = useState("");
  const [destino, setDestino] = useState(otrasCuentas[0]?.id ? String(otrasCuentas[0].id) : "");
  const [destinoManual, setDestinoManual] = useState("");
  const [enviando, setEnviando] = useState(false);
  const [error, setError] = useState(null);

  const tope =
    tipo === "devolver"
      ? Number(bolsillo?.saldo ?? 0)
      : tipo === "deposito"
        ? MAXIMO_TRANSACCION
        : Math.min(Number(disponible ?? 0), MAXIMO_TRANSACCION);

  const enviar = async (evento) => {
    evento.preventDefault();
    setEnviando(true);
    setError(null);

    const base = { monto: Number(monto) };
    if (descripcion.trim()) base.descripcion = descripcion.trim();

    try {
      if (tipo === "retiro") await retirar({ ...base, cuentaOrigenId: cuenta.id });
      if (tipo === "deposito") await depositar({ ...base, cuentaDestinoId: cuenta.id });
      if (tipo === "transferencia") {
        const cuentaDestinoId = Number(destino === "otra" ? destinoManual : destino);
        await transferir({ ...base, cuentaOrigenId: cuenta.id, cuentaDestinoId });
      }
      if (tipo === "apartar") await apartar(bolsillo.id, base);
      if (tipo === "devolver") await devolver(bolsillo.id, base);
      alTerminar(TEXTOS[tipo].exito);
    } catch (fallo) {
      setError(fallo);
    } finally {
      setEnviando(false);
    }
  };

  return (
    <form className="formulario" onSubmit={enviar} noValidate={false}>
      {tipo === "transferencia" ? (
        <>
          <Campo etiqueta="Cuenta destino">
            {(props) => (
              <select
                {...props}
                className="selector"
                value={destino}
                onChange={(evento) => setDestino(evento.target.value)}
              >
                {otrasCuentas.map((otra) => (
                  <option key={otra.id} value={otra.id}>
                    Mi cuenta {otra.numeroCuenta}
                  </option>
                ))}
                <option value="otra">Cuenta de otra persona (por ID)</option>
              </select>
            )}
          </Campo>
          {destino === "otra" || otrasCuentas.length === 0 ? (
            <Campo etiqueta="ID de la cuenta destino" ayuda="Pídale el número interno de cuenta al destinatario.">
              {(props) => (
                <input
                  {...props}
                  className="entrada num"
                  type="number"
                  min="1"
                  step="1"
                  required
                  value={destinoManual}
                  onChange={(evento) => {
                    setDestino("otra");
                    setDestinoManual(evento.target.value);
                  }}
                />
              )}
            </Campo>
          ) : null}
        </>
      ) : null}

      <CampoMonto
        valor={monto}
        alCambiar={setMonto}
        maximo={tope > 0 ? tope : undefined}
        ayuda={
          tipo === "deposito"
            ? `Máximo ${formatoPesos(MAXIMO_TRANSACCION)} por movimiento.`
            : `Puede mover hasta ${formatoPesos(Math.max(tope, 0))}.`
        }
      />

      <Campo etiqueta="Descripción (opcional)">
        {(props) => (
          <input
            {...props}
            className="entrada"
            maxLength={120}
            value={descripcion}
            onChange={(evento) => setDescripcion(evento.target.value)}
          />
        )}
      </Campo>

      <AvisoError error={error} />

      <div className="acciones">
        <button className="boton" type="submit" disabled={enviando || !monto}>
          {enviando ? "Enviando…" : TEXTOS[tipo].boton}
        </button>
      </div>
    </form>
  );
}

import { useEffect, useState } from "react";
import { CLAVE_TEMA, aplicarTema, leerTema } from "../utils/tema";

const SIGUIENTE = { sistema: "claro", claro: "oscuro", oscuro: "sistema" };
const TEXTO = { sistema: "Tema: sistema", claro: "Tema: claro", oscuro: "Tema: oscuro" };

export function SelectorTema() {
  const [tema, setTema] = useState(leerTema);

  // Sincroniza con sistemas externos (DOM y localStorage), sin setState.
  useEffect(() => {
    aplicarTema(tema);
    try {
      localStorage.setItem(CLAVE_TEMA, tema);
    } catch {
      // Sin almacenamiento: el tema dura hasta recargar.
    }
  }, [tema]);

  return (
    <button
      type="button"
      className="boton boton--fantasma"
      onClick={() => setTema((actual) => SIGUIENTE[actual])}
      aria-label={`${TEXTO[tema]}. Cambiar tema`}
      title="Cambiar entre tema del sistema, claro y oscuro"
    >
      {TEXTO[tema]}
    </button>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";

/**
 * Ejecuta una carga asíncrona y expone sus tres estados (cargando, error,
 * datos) más `recargar`. Ignora respuestas que llegan después de desmontar
 * o de una carga más reciente.
 */
export function useCarga(cargador, dependencias = []) {
  const [estado, setEstado] = useState({ cargando: true, error: null, datos: null });
  const turno = useRef(0);

  // eslint-disable-next-line react-hooks/exhaustive-deps
  const cargar = useCallback(cargador, dependencias);

  const recargar = useCallback(async () => {
    const mio = ++turno.current;
    setEstado((previo) => ({ ...previo, cargando: true, error: null }));
    try {
      const datos = await cargar();
      if (mio === turno.current) setEstado({ cargando: false, error: null, datos });
    } catch (error) {
      if (mio === turno.current) setEstado({ cargando: false, error, datos: null });
    }
  }, [cargar]);

  useEffect(() => {
    recargar();
    return () => {
      turno.current += 1;
    };
  }, [recargar]);

  return { ...estado, recargar };
}
